# Count coach sessions in different time windows
python3 << 'PYEOF'
import os, json

sess_dir = ".state/sessions/history"
now_ms = 1774298369872

windows = {
    "Last 6h": now_ms - 6*3600*1000,
    "6-12h ago": now_ms - 12*3600*1000,
    "12-24h ago": now_ms - 24*3600*1000,
}

for label, cutoff in windows.items():
    upper = cutoff + 6*3600*1000 if "ago" in label else now_ms
    coach_count = 0
    coach_kb = 0
    gym_count = 0
    for s in os.listdir(sess_dir):
        parts = s.split("_")
        if len(parts) < 2:
            continue
        try:
            ts = int(parts[1])
        except:
            continue

        if "ago" in label:
            if ts <= cutoff or ts > upper:
                continue
        else:
            if ts <= cutoff:
                continue

        meta_path = os.path.join(sess_dir, s, "meta.json")
        if not os.path.exists(meta_path):
            continue
        try:
            with open(meta_path) as f:
                meta = json.load(f)
            if meta.get("agent") == "coach":
                coach_count += 1
                jpath = os.path.join(sess_dir, s, "session.jsonl")
                if os.path.exists(jpath):
                    coach_kb += os.path.getsize(jpath) / 1024
                task = meta.get("task", {})
                if isinstance(task, dict):
                    msg = task.get("message", "")
                else:
                    msg = str(task)
                if "common-sense" in msg or "training" in msg or "gym" in msg.lower():
                    gym_count += 1
        except:
            continue

    print(f"{label}: {coach_count} coach sessions ({gym_count} gym/verify), {coach_kb:.0f}K total")
PYEOF
